DO $validate$ BEGIN IF (SELECT count(*) FROM public."artifact_snapshots" c LEFT JOIN public."artifact_template_versions" p ON c."template_version_id" = p.id WHERE c."template_version_id" IS NOT NULL  AND (p.id IS NULL OR (p.organization_id IS NOT NULL AND p.organization_id IS DISTINCT FROM c.organization_id))) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_adec74a6f3c9'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."artifact_template_versions" c LEFT JOIN public."artifact_templates" p ON c."template_id" = p.id WHERE c."template_id" IS NOT NULL  AND (p.id IS NULL OR (p.organization_id IS NOT NULL AND p.organization_id IS DISTINCT FROM c.organization_id))) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_9fbaf4a4e8eb'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."business_unit_memberships" c LEFT JOIN public."roles" p ON c."role_id" = p.id WHERE c."role_id" IS NOT NULL  AND (p.id IS NULL OR (p.organization_id IS NOT NULL AND p.organization_id IS DISTINCT FROM c.organization_id))) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_c1029b9b9b65'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."checklist_templates" c LEFT JOIN public."artifact_templates" p ON c."artifact_template_id" = p.id WHERE c."artifact_template_id" IS NOT NULL  AND (p.id IS NULL OR (p.organization_id IS NOT NULL AND p.organization_id IS DISTINCT FROM c.organization_id))) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_c275c1e6c06d'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."identity_invitations" c LEFT JOIN public."roles" p ON c."role_id" = p.id WHERE c."role_id" IS NOT NULL  AND (p.id IS NULL OR (p.organization_id IS NOT NULL AND p.organization_id IS DISTINCT FROM c.organization_id))) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_5477b1014c26'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."organization_memberships" c LEFT JOIN public."roles" p ON c."role_id" = p.id WHERE c."role_id" IS NOT NULL  AND (p.id IS NULL OR (p.organization_id IS NOT NULL AND p.organization_id IS DISTINCT FROM c.organization_id))) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_21961f459898'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."report_templates" c LEFT JOIN public."artifact_templates" p ON c."artifact_template_id" = p.id WHERE c."artifact_template_id" IS NOT NULL  AND (p.id IS NULL OR (p.organization_id IS NOT NULL AND p.organization_id IS DISTINCT FROM c.organization_id))) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_a151017d4b7d'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."operation_assets" c JOIN public."operations" p ON c."operation_id" = p.id JOIN public."assets" q ON c."asset_id"=q.id WHERE p.organization_id IS DISTINCT FROM q.organization_id) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_operation_assets'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."quote_assets" c JOIN public."quotes" p ON c."quote_id" = p.id JOIN public."assets" q ON c."asset_id"=q.id WHERE p.organization_id IS DISTINCT FROM q.organization_id) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_quote_assets'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."pmoc_plan_units" c JOIN public."pmoc_plans" p ON c."plan_id" = p.id JOIN public."pmoc_units" q ON c."unit_id"=q.id WHERE p.organization_id IS DISTINCT FROM q.organization_id) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_pmoc_plan_units'; END IF; END $validate$;
DO $validate$ BEGIN IF (SELECT count(*) FROM public."scheduling_resource_allocations" c JOIN public."scheduling_events" p ON c."event_id" = p.id JOIN public."assets" q ON c."asset_id"=q.id WHERE p.organization_id IS DISTINCT FROM q.organization_id) > 0 THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Relational integrity validation failed: pr12_scheduling_resource_allocations'; END IF; END $validate$;
DO $permissions$ DECLARE item record; BEGIN
    FOR item IN SELECT DISTINCT p.oid::regprocedure AS signature,r.rolname FROM pg_proc p
      JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(p.proacl) a
      JOIN pg_roles r ON r.oid=a.grantee
      WHERE n.nspname='public' AND p.proname IN ('pr12_check_scope','pr12_rvt_asset_scope','pr12_rvt_occurrence_assets') AND a.grantee<>p.proowner
    LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',item.signature,item.rolname); END LOOP;
  END $permissions$;
COMMIT;
